"Say the next number by adding {N}.":"Di nonb ki vin apre a lè ou ajoute {N}.",
"After {N} ones comes a new ten: {N}, {N}.":"Apre {N} inite, yon nouvo dizèn kòmanse: {N}, {N}.",
"After {N} comes {N}, then {N}, {N} and on to {N}.":"Apre {N} se {N}, apre sa {N}, {N}, epi kontinye jiska {N}.",
"What number is one more?":"Ki nonb ki gen youn anplis?",
"When the ones reach {N}, the next number starts a new ten.":"Lè inite yo rive nan {N}, nonb ki vin apre a kòmanse yon nouvo dizèn.",
