"{N} + {N} = {N} is a double.":"{N} + {N} = {N} se yon doub.",
"{N} + {N} is a near double: one more than {N} + {N}.":"{N} + {N} se yon prèske doub: youn anplis pase {N} + {N}.",
"So {N} + {N} = {N}.":"Kidonk {N} + {N} = {N}.",
