"Hide some coins under a cup: \"There were {N}, now I see {N}.":"Kache kèk pyès lajan anba yon tas: \"Te gen {N}, kounye a mwen wè {N}.",
"How many are hiding?\"":"Konbyen ki kache?\"",
"What the equal sign means":"Sa siy egal la vle di",
