"Fill the ten-frame first, then add what is left.":"Ranpli kad dis la an premye, apre sa ajoute sa ki rete.",
"Use an egg carton cut to {N} cups.":"Sèvi ak yon bwat ze ou koupe pou l gen {N} twou.",
"Fill it first, then count what is left.":"Ranpli l an premye, apre sa konte sa ki rete.",
"Fact families":"Fanmi operasyon",
"Adding and subtracting are a family.":"Adisyon ak soustraksyon se yon fanmi.",
"{N} + {N} = {N}, so {N} − {N} = {N} and {N} − {N} = {N}.":"{N} + {N} = {N}, kidonk {N} − {N} = {N} ak {N} − {N} = {N}.",
"If you know one fact, you know the family.":"Si ou konnen yon operasyon, ou konnen tout fanmi an.",
"What adding fact uses these numbers?":"Ki adisyon ki sèvi ak nonb sa yo?",
"Taking away undoes adding.":"Retire defèt sa adisyon fè.",
"Write one fact like {N} + {N} = {N} and ask your child for the other three in the family.":"Ekri yon operasyon tankou {N} + {N} = {N} epi mande pitit ou twa lòt yo nan fanmi an.",
"Add {N}-digit numbers, no regrouping":"Adisyone nonb {N} chif, san regwoupman",
