"Add two ages or two prices under ${N} by adding dimes to dimes and pennies to pennies.":"Adisyone de laj oswa de pri ki pa rive ${N} lè ou mete pyès 10 santim ak pyès 10 santim, pyès 1 santim ak pyès 1 santim.",
"Add {N}-digit numbers by making a ten":"Adisyone nonb {N} chif lè ou fè yon dizèn",
"Too many ones for one dock!":"Twòp inite pou yon sèl waf!",
