"Hi, I'm Pip!":"Bonjou, mwen se Pip!",
"I'm a helper made by the Tenbright team using a computer, and my voice is made by a computer too.":"Mwen se yon èd ekip Tenbright fè ak yon òdinatè, e se yon òdinatè ki fè vwa m tou.",
"I collect light-beads.":"Mwen ranmase pèl limyè.",
"Ten beads make a lantern.":"Dis pèl fè yon lantèn.",
"Will you help me light the Kingdom?":"Èske ou ap ede m klere Wayòm nan?",
"Hint":"Endis",
"Try again.":"Eseye ankò.",
"Homeschool or not sure":"Lekòl lakay oswa mwen pa sèten",
"How long we keep it":"Konbyen tan nou kenbe yo",
"How we use it":"Kijan nou sèvi ak yo",
"How we'll know":"Kijan n ap konnen",
"Hundreds are the same, so look at the ones.":"Santèn yo menm, kidonk gade inite yo.",
"I agree that Tenbright may keep my child's learning record on this device to choose their next activity and show me their progress.":"Mwen dakò pou Tenbright kenbe dosye aprantisaj pitit mwen sou aparèy sa a pou chwazi pwochen aktivite li epi montre m pwogrè li.",
"I am this child's parent or legal guardian.":"Mwen se paran oswa gadyen legal timoun sa a.",
"I found {N} lanterns you can already light.":"Mwen jwenn {N} lantèn ou ka limen deja.",
"Now the map knows where to start.":"Kounye a kat la konnen ki kote pou l kòmanse.",
"I worked this out, but I made a mistake.":"Mwen rezoud sa, men mwen fè yon erè.",
"Can you find it?":"Èske ou ka jwenn li?",
"I wrote it":"Mwen ekri l",
"If we change what we collect or how we use it, we will ask for your consent again before the change applies to your child.":"Si nou chanje sa nou ranmase oswa kijan nou sèvi avè l, n ap mande w konsantman ou ankò anvan chanjman an aplike pou pitit ou.",
"If you switch on voice answers on the grown-ups page, your child can tap the Talk button and say a number or a short command such as \"next\".":"Si ou aktive repons pa vwa nan paj granmoun yo, pitit ou ka peze bouton Pale a epi di yon nonb oswa yon ti kòmand tankou \"swivan\".",
"Speech is turned into text by your browser on this device; Tenbright uses it only if the browser can promise this happens on the device.":"Navigatè w la chanje pawòl yo an tèks sou aparèy sa a; Tenbright sèvi avè l sèlman si navigatè a ka garanti sa fèt sou aparèy la.",
"The words are used once to read the answer and are then discarded.":"Nou sèvi ak mo yo yon sèl fwa pou li repons lan, epi apre sa nou jete yo.",
"No audio and no transcript is recorded, kept or sent to us or anyone else.":"Okenn son ni okenn tèks pa anrejistre, pa kenbe, ni pa voye ba nou oswa ba nenpòt lòt moun.",
"The microphone is used only after a tap on Talk, for one short answer.":"Mikwo a mache sèlman apre yon moun peze Pale, pou yon sèl ti repons.",
"Pip never asks your child to say their name or anything about themselves.":"Pip pa janm mande pitit ou di non l oswa anyen sou tèt li.",
"You can switch voice answers off at any time.":"Ou ka fèmen repons pa vwa nenpòt ki lè.",
"In the full product this step will use an FTC-recognized method of verifiable parental consent.":"Nan vèsyon konplè a, etap sa a ap sèvi ak yon metòd konsantman paran ki ka verifye, FTC rekonèt.",
"This preview records your agreement on this device only.":"Vèsyon esè sa a anrejistre akò ou sou aparèy sa a sèlman.",
"In this preview, everything stays in this browser on this device.":"Nan vèsyon esè sa a, tout bagay rete nan navigatè sa a, sou aparèy sa a.",
"Nothing is sent to us or to anyone else.":"Anyen pa voye ba nou ni ba okenn lòt moun.",
"The app loads no outside fonts, analytics, ads or trackers.":"Aplikasyon an pa chaje okenn polis ekriti deyò, okenn zouti analiz, okenn piblisite ni okenn zouti pou swiv moun.",
"Pip's voice is recorded audio made with an AI voice model and included in the app; if a sentence has no recording, a voice built into your device reads it.":"An anglè, vwa Pip la se son anrejistre ki fèt ak yon modèl vwa IA epi ki mete nan aplikasyon an; nan lòt lang yo, oswa si yon fraz pa gen anrejistreman, se yon vwa ki deja nan aparèy ou a ki li l.",
"Speech recognition, if you turn it on, runs only on your device.":"Rekonesans vwa, si ou aktive l, mache sèlman sou aparèy ou a.",
"Just looking?":"W ap jis gade?",
