"Use money: a dime is {N}/{N} of a dollar and a penny is {N}/{N}.":"Sèvi ak lajan: yon pyès 10 santim se {N}/{N} yon dola, yon pyès 1 santim se {N}/{N}.",
"Compare decimals":"Konpare desimal",
