"Write both with the same number of decimal places.":"Ekri tou de ak menm kantite plas desimal.",
"Compare like whole numbers: {N} > {N}.":"Konpare yo tankou nonb antye: {N} > {N}.",
"Compare the tenths first.":"Konpare dizyèm yo an premye.",
"Tenths first, then hundredths.":"Dizyèm an premye, apre sa santyèm.",
"Compare prices like ${N} and ${N} at the store.":"Konpare pri tankou ${N} ak ${N} nan magazen an.",
