"Do things in the right order.":"Fè bagay yo nan bon lòd.",
"Parentheses first.":"Parantèz an premye.",
"Then multiply or divide.":"Apre sa miltipliye oswa divize.",
"Then add or subtract.":"Apre sa adisyone oswa soustrè.",
"What is inside the parentheses?":"Kisa ki anndan parantèz yo?",
