"Pip did the first step and then stopped.":"Pip fè premye etap la epi li kanpe.",
"Pip added the numbers shown instead of finding the missing part.":"Pip adisyone nonb ki parèt yo olye li jwenn pati ki manke a.",
"Pip thought = means \"write the answer next\".":"Pip te panse = vle di \"ekri repons lan apre\".",
"Pip changed the ones instead of the tens.":"Pip chanje inite yo olye dizèn yo.",
"Pip counted the parts that are not shaded.":"Pip konte pati ki pa kolore yo.",
"Pip counted the tick marks instead of the jumps.":"Pip konte mak yo olye sote yo.",
"Pip added the same number to the top and bottom instead of multiplying.":"Pip ajoute menm nonb lan anwo ak anba olye li miltipliye.",
"Pip thought a bigger bottom number means a bigger fraction.":"Pip te panse yon pi gwo nonb anba vle di yon pi gwo fraksyon.",
"Pip added the bottom numbers too.":"Pip adisyone nonb anba yo tou.",
"Pip just added the whole number to the top.":"Pip jis ajoute nonb antye a nan nonb anwo a.",
"Pip added tenths and hundredths without changing the tenths first.":"Pip adisyone dizyèm ak santyèm san li pa chanje dizyèm yo an premye.",
