"Pip divided the other way round.":"Pip divize nan lòt sans lan.",
"Pip multiplied the top of one fraction by the bottom of the other.":"Pip miltipliye nonb anwo yon fraksyon pa nonb anba lòt la.",
"Pip made the pieces bigger instead of smaller.":"Pip fè moso yo vin pi gwo olye pi piti.",
"Pip wrote hundredths in the tenths place.":"Pip ekri santyèm nan plas dizyèm yo.",
"Pip thought the decimal with more digits is bigger.":"Pip te panse desimal ki gen plis chif la pi gran.",
"Pip stuck zeros on the end instead of moving the digits.":"Pip kole zewo nan bout la olye li deplase chif yo.",
"Pip mixed up the tenths and hundredths places.":"Pip melanje plas dizyèm ak plas santyèm.",
