"Dividing by {N} makes each digit worth one thousandth as much.":"Divize pa {N} fè chak chif vo yon milyèm sa li te vo.",
"Each of the {N} wholes holds {N} of them.":"Chak nan {N} inite antye yo kenbe {N} ladan yo.",
"Each one gets {N}/{N}.":"Chak moun resevwa {N}/{N}.",
"Each place is worth one tenth of the place on its left.":"Chak plas vo yon dizyèm plas ki agoch li a.",
"Each share gets {N} piece of size {N}/{N}.":"Chak pa resevwa {N} moso ki gwosè {N}/{N}.",
