"Written adding, subtracting and multiplying all lean on it.":"Adisyon, soustraksyon ak miltiplikasyon alekri tout apiye sou li.",
"Adding and subtracting come up in almost every later topic, from money to fractions.":"Adisyon ak soustraksyon parèt nan prèske tout sijè ki vini apre, depi lajan rive nan fraksyon.",
"Multiplying and dividing are the base for fractions, area and most of Grades {N} and {N}.":"Miltiplikasyon ak divizyon se baz fraksyon, sifas ak pi fò nan Ane {N} ak Ane {N}.",
"Word problems connect the math to real situations: choosing what to do, not only how to do it.":"Pwoblèm istwa yo konekte matematik ak sitiyasyon reyèl: chwazi sa pou fè, pa sèlman kijan pou fè l.",
"Patterns, expressions and mixed review keep skills connected and fresh.":"Modèl, ekspresyon ak revizyon melanje kenbe konpetans yo konekte e fre.",
"Fractions describe parts of a whole and lead to decimals and measurement.":"Fraksyon dekri pati yon antye epi yo mennen nan desimal ak mezi.",
"Decimals extend place value past the ones place and are used for money and measuring.":"Desimal yo pwolonje valè pozisyon pi lwen pase inite yo epi yo sèvi pou lajan ak mezi.",
"Counting money uses place value and adding in a setting children meet every day.":"Konte lajan sèvi ak valè pozisyon ak adisyon nan yon sitiyasyon timoun yo rankontre chak jou.",
"Reading clocks and finding time passed use counting by {N}s and the {N} minutes in an hour.":"Li revèy ak jwenn tan ki pase sèvi ak konte {N1} pa {N1} ak {N2} minit ki nan yon èdtan.",
"Measuring connects numbers to real lengths, and area is a picture of multiplying.":"Mezire konekte nimewo ak vrè longè, e sifas se yon imaj miltiplikasyon.",
"Shapes, angles and grids are the start of geometry and of reading graphs and maps.":"Fòm, ang ak kadriyaj se kòmansman jewometri ak lekti graf ak kat.",
"Every Grade {N} skill is lit, so Pip moves on.":"Tout konpetans Ane {N} yo limen, kidonk Pip ale pi lwen.",
"A grid numbered {N} to {N} across the bottom and up the side.":"Yon kadriyaj ki gen nimewo {N} rive {N} anba ak sou kote a.",
