"Revenue, cost and profit":"Revni, depans ak pwofi",
"Saving plan: weeks to a goal":"Plan epay: semèn jiska objektif la",
"Share of a company":"Pati nan yon konpayi",
"Growth year by year":"Kwasans ane apre ane",
"Opens when you can do revenue, cost and profit.":"Li louvri lè ou konn fè revni, depans ak pwofi.",
"Revenue as profit":"Revni pran pou pwofi",
"Forgot a cost":"Bliye yon depans",
"Added the costs":"Adisyone depans yo",
"Growth added once":"Ajoute kwasans lan yon sèl fwa",
"Whole instead of part":"Tout olye pati a",
"Gives all the money that came in when the question asks for the profit left after costs.":"Li bay tout lajan ki antre lè kesyon an mande pwofi ki rete apre depans yo.",
"Takes away one cost but not another one in the story.":"Li retire yon depans men li pa retire yon lòt ki nan istwa a.",
"Adds the costs to the money that came in instead of taking them away.":"Li adisyone depans yo ak lajan ki antre olye pou l retire yo.",
"Adds the first year’s growth again instead of growing the new, bigger amount.":"Li ajoute kwasans premye ane a ankò olye pou l fè nouvo kantite a, ki pi gwo, grandi.",
"Gives the whole company’s profit to one owner instead of the owner’s share of it.":"Li bay yon sèl pwopriyetè tout pwofi konpayi an olye pati pa l.",
"That is all the money in.":"Sa se tout lajan ki antre.",
"What is left after costs?":"Kisa ki rete apre depans yo?",
"Look again.":"Gade ankò.",
"Is there another cost?":"Èske gen yon lòt depans?",
"Costs are money going out.":"Depans se lajan k ap soti.",
"Take them away.":"Retire yo.",
"This year the tenth is of the new amount.":"Ane sa a, dizyèm nan se sou nouvo kantite a.",
"You own only some of the shares.":"Ou genyen sèlman kèk nan aksyon yo.",
"Find your part.":"Jwenn pati pa w.",
