"Pip added the costs instead of taking them away.":"Pip adisyone depans yo olye pou l retire yo.",
"Pip added the first year’s growth again.":"Pip ajoute kwasans premye ane a ankò.",
"Pip gave the whole profit to one owner.":"Pip bay yon sèl pwopriyetè tout pwofi a.",
"Pip runs a market stall.":"Pip ap okipe yon ti machann nan mache a.",
"When every item costs the same, multiply.":"Lè chak bagay koute menm pri, miltipliye.",
"The number of items times the price is the total.":"Kantite bagay yo fwa pri a se total la.",
