"How much is in each group?":"Konbyen ki nan chak gwoup?",
"The number of items times the price.":"Kantite bagay yo fwa pri a.",
"At the store, pick something you could buy several of and work out the total together.":"Nan magazen an, chwazi yon bagay nou ta ka achte plizyè epi kalkile total la ansanm.",
"Did the lemonade stand make money?":"Èske ti machann limonad la fè lajan?",
"Revenue is all the money that comes in.":"Revni se tout lajan ki antre.",
"Costs are the money that goes out.":"Depans se lajan ki soti.",
