"Find the money in first.":"Jwenn lajan ki antre a anvan.",
"Then take away every cost.":"Apre sa retire chak depans.",
"Revenue take away every cost.":"Revni mwens chak depans.",
"Plan a pretend bake sale together: the price, how many, and what the ingredients cost.":"Planifye ansanm yon pretann lavant gato: pri a, konbyen, ak konbyen engredyan yo koute.",
"Saving for something special.":"Epay pou yon bagay espesyal.",
"First find how much is still needed.":"Anvan, jwenn konbyen ki manke toujou.",
