"Owning part of a company.":"Posede yon pati nan yon konpayi.",
"A company can be split into equal parts called shares.":"Yo ka separe yon konpayi an pati egal yo rele aksyon.",
"Owning some shares means owning part of the company.":"Genyen kèk aksyon vle di posede yon pati nan konpayi an.",
"Each share gets an equal part of the profit.":"Chak aksyon resevwa yon pati egal nan pwofi a.",
"Profit can be smaller next year, so a share is not a promise.":"Pwofi a ka pi piti ane pwochèn, kidonk yon aksyon pa yon pwomès.",
"How much does one share get?":"Konbyen yon aksyon resevwa?",
"The profit for one share, times the shares you own.":"Pwofi pou yon aksyon, fwa aksyon ou genyen yo.",
"Cut a paper company into equal shares and split a pretend profit between the owners.":"Koupe yon konpayi an papye an aksyon egal epi separe yon pretann pwofi bay pwopriyetè yo.",
"The money-growing mystery.":"Mistè lajan k ap grandi a.",
"Each year the jar grows by one tenth of what is in it.":"Chak ane bokal la grandi yon dizyèm sa ki ladan l.",
"Find one tenth, then add it.":"Jwenn yon dizyèm, apre sa ajoute l.",
"Next year, find one tenth of the new, bigger amount.":"Ane pwochèn, jwenn yon dizyèm nouvo kantite a, ki pi gwo a.",
"Growth on growth is called compound growth.":"Kwasans sou kwasans rele kwasans konpoze.",
