"Interest and compound growth":"Enterè ak kwasans konpoze",
"Families save a little at a time to buy something later.":"Fanmi yo epay ti kras pa ti kras pou achte yon bagay pita.",
"Before buying, people check how much money will be left.":"Anvan yo achte, moun yo verifye konbyen lajan ki pral rete.",
"People set a goal and count up to see how much more they need.":"Moun yo fikse yon objektif epi yo konte monte pou wè konbyen ki manke.",
"Cashiers count coins starting with the ones worth the most.":"Kesye yo konte pyès yo kòmanse ak sa ki vo plis yo.",
"Shoppers count up from the price to check their change.":"Achtè yo konte apati pri a pou verifye monnen yo.",
"People decide what to spend now and what to save for later.":"Moun yo deside sa pou yo depanse kounye a ak sa pou yo epay pou pita.",
"Shops multiply the price by how many to find a total.":"Magazen yo miltipliye pri a pa kantite a pou jwenn total la.",
"People who own shares own part of a company and get part of its profit.":"Moun ki gen aksyon posede yon pati nan yon konpayi epi yo resevwa yon pati nan pwofi li.",
"Banks add interest to savings, and the interest can grow on itself.":"Bank yo ajoute enterè sou epay yo, epi enterè a ka grandi sou tèt li.",
"Count the coins in a jar together, add a few, and count again.":"Konte pyès ki nan yon bokal ansanm, ajoute kèk, epi konte ankò.",
