"Choose something your child wants and work out together how much more is needed.":"Chwazi yon bagay pitit ou vle epi kalkile ansanm konbyen ki manke.",
"Empty a coin jar together and count it, biggest coins first.":"Vide yon bokal pyès ansanm epi konte yo, pi gwo yo anvan.",
"At a store, guess the change before the cashier gives it.":"Nan yon magazen, devine monnen an anvan kesye a bay li.",
