"Shops try different prices: a higher price can mean fewer sales.":"Magazen yo eseye pri diferan: yon pri ki pi wo ka vle di mwens lavant.",
"When costs are bigger than sales, a business has a loss that day.":"Lè depans yo pi gwo pase lavant yo, yon biznis fè pèt jou sa a.",
"Shoppers round prices to check quickly whether a list fits their money.":"Achtè yo awondi pri yo pou verifye vit si yon lis antre nan lajan yo.",
"Prices use a decimal point: dollars on the left, cents on the right.":"Pri yo sèvi ak yon pwen desimal: dola sou bò gòch, santim sou bò dwat.",
"Shelf labels often show the price for one, so shoppers can compare packs.":"Etikèt sou etajè yo souvan montre pri pou youn, pou achtè yo ka konpare pake yo.",
"Friends who share a meal often divide the bill so each pays the same.":"Zanmi ki pataje yon manje souvan divize bòdwo a pou chak moun peye menm kantite.",
"Some companies pay part of their profit to the people who own shares.":"Kèk konpayi peye yon pati nan pwofi yo bay moun ki gen aksyon.",
"Businesses compare the cost of one item in small and big packs.":"Biznis yo konpare pri yon bagay nan ti pake ak gwo pake.",
"Money saved earlier has more years to grow.":"Lajan ou epay pi bonè gen plis ane pou l grandi.",
"The price of a share goes up and down; going up last week does not mean it will next week.":"Pri yon aksyon monte epi desann; li te monte semèn pase a pa vle di l ap monte semèn pwochèn.",
"Ask: if a toy cost twice as much, would as many people buy it?":"Mande: si yon jwèt te koute de fwa plis, èske menm kantite moun ta achte l?",
"Talk about a time plans changed because of the weather, and what it cost.":"Pale sou yon fwa plan yo te chanje akoz tan an, ak konbyen sa te koute.",
"Before checkout, round each item on a short list and estimate the total together.":"Anvan ou peye, awondi chak bagay sou yon ti lis epi estime total la ansanm.",
"At the store, find two pack sizes of the same thing and work out the price for one.":"Nan magazen an, jwenn de gwosè pake pou menm bagay la epi kalkile pri pou youn.",
"Share a pretend bill for a family meal and work out each person’s part.":"Pataje yon pretann bòdwo pou yon manje fanmi epi kalkile pati chak moun.",
"Ask: if a company makes more profit, what happens to each owner’s part?":"Mande: si yon konpayi fè plis pwofi, kisa ki rive pati chak pwopriyetè?",
